DROP INDEX [CCI_Fact] ON [sales].[Fact];
GO
DROP INDEX [NCCI_Old] ON [sales].[Old];
GO
ALTER TABLE [sales].[Old] DROP COLUMN [V];
GO
CREATE CLUSTERED COLUMNSTORE INDEX [CCI_Fact] ON [sales].[Fact] ORDER ([DateKey]) WITH (DATA_COMPRESSION = COLUMNSTORE_ARCHIVE);
GO
CREATE NONCLUSTERED COLUMNSTORE INDEX [NCCI_Order] ON [sales].[Order] ([OrderId], [Total]) WHERE [Total] > 0 WITH (COMPRESSION_DELAY = 10);
GO
